      return false;
    }

    int month = int.parse(parts[0]);
    int day = int.parse(parts[1]);
    int year = int.parse(parts[2]);

    if (month < 1 || month > 12) {
      return false;
    }

    if ([1, 3, 5, 7, 8, 10, 12].contains(month) && (day < 1 || day > 31)) {
      return false;
    }

    if ([4, 6, 9, 11].contains(month) && (day < 1 || day > 30)) {
      return false;
    }

    if (month == 2 && (day < 1 || day > 29)) {
